const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export const CASCADE_BRANCHES=[
 {id:'repo',key:'access',title:['Repo-Zugang','gefährdet?'],action:['Arbeitsrepo umziehen','nach Anleitung'],explain:'Wenn der bisherige Repo-Zugang endet, kann Anna ihre vollständige lokale Git-Kopie auf einen anderen geeigneten Dienst übertragen. Vorher abgleichen, danach eine frische Kopie und den Ausgabeweg prüfen. Der Umzug ist mit einer verständlichen Anleitung selbstständig möglich.'},
 {id:'tool',key:'license',title:['oXygen-Berechtigung','gefährdet?'],action:['Berechtigung klären oder','passendes Werkzeug wählen'],explain:'Endet eine Campusberechtigung, klärt Anna einen anderen zulässigen Zugang oder probiert ein geeignetes XML-Werkzeug aus. Ihre TEI-Dateien und Git-Geschichte bleiben grundsätzlich verwendbar. Eingabe, Schema und Vorschau werden im neuen Arbeitsweg geprüft.'},
 {id:'advice',key:'advice',title:['Beratung','weiter verfügbar?'],action:['Anleitungen pflegen; bei Bedarf','Ersatzberatung vereinbaren'],explain:'Fehlende Beratung kann Einrichtung und Wartung erschweren. Verständliche Anleitungen, ein einfacher lokaler Ausgabeweg und ein erreichbarer Ersatzkontakt helfen. Nicht jeder Schritt braucht direkte Hilfe: Der einfache Repo-Umzug kann nach Anleitung erfolgen.'},
 {id:'publication',key:'publicationService',title:['Institutionelle Publikations-','dienste weiter verfügbar?'],action:['Publikations-Host und','Ausgabeweg prüfen'],explain:'Auch Webhosting, automatische Ausgabeerzeugung oder andere institutionelle Publikationsdienste können betroffen sein. Anna prüft die konkreten Vereinbarungen, Konten und Webadressen. Ein neuer Arbeits-Host löst diese Fragen nicht automatisch; ein lokal ausführbarer Build und ein separates Publikationsrepo erleichtern den Wechsel.'}
];
export function branchStatus(branch,state){if(!state)return 'Mögliche Folge · gesondert klären';if(branch.id==='tool'&&state.format==='markdown')return 'Hier nicht vorausgesetzt';if(branch.id==='advice'&&state.host==='uni-only')return 'Bereits nicht im Angebot';return {unknown:'Noch ungeklärt',ends:'Endet · Handlungsbedarf',stays:'Bleibt nachweislich verfügbar'}[state[branch.key]]||'Noch ungeklärt';}
export function cascadeSVG(state=null,interactive=false){
 const box=(x,y,w,h,lines,fill='#e6f2fc',stroke='#bdced9',attrs='')=>`<g ${attrs}><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="17" fill="${fill}" stroke="${stroke}" stroke-width="1.5"/>${lines.map((t,i)=>`<text x="${x+w/2}" y="${y+h/2-(lines.length-1)*12+6+i*24}" text-anchor="middle" font-size="${i===2?14:18}" fill="#164b70">${esc(t)}</text>`).join('')}</g>`;
 const path=d=>`<path d="${d}" stroke="#9baeb4" stroke-width="1.6" fill="none" marker-end="url(#cascade-arrow)"/>`;
 let lines='',nodes='';
 for(const [i,b] of CASCADE_BRANCHES.entries()){const x=25+i*295,cx=x+132.5,status=branchStatus(b,state);const v=state?.[b.key];const color=status==='Hier nicht vorausgesetzt'||status==='Bereits nicht im Angebot'?'#a0aaa8':v==='ends'?'#a24736':v==='stays'?'#285b44':'#bdced9';const fill=status==='Hier nicht vorausgesetzt'||status==='Bereits nicht im Angebot'?'#f0f2ef':v==='ends'?'#fbede7':v==='stays'?'#e8f0df':'#e6f2fc';
 lines+=path(`M600 100V145H${cx}V210`)+path(`M${cx} 300V360`)+path(`M${cx} 445V490H600V550`);
 const attrs=interactive?`class="cascade-node" role="button" tabindex="0" data-cascade-node="${b.id}" aria-label="${esc(b.title.join(' '))}: ${esc(status)}. Folgen und Maßnahmen erklären"`:`role="img" aria-label="${esc(b.title.join(' '))}: ${esc(status)}"`;
 const actions=status==='Hier nicht vorausgesetzt'||status==='Bereits nicht im Angebot'?['Keine zusätzliche Umstellung','aus diesem Anlass']:v==='stays'?['Bestehenden Zugang nutzen','Verfügbarkeit dokumentieren']:[...b.action,v==='ends'?'Geplante Reaktion':'Bei entsprechendem Bedarf'];
 nodes+=box(x,210,265,90,[...b.title,status],fill,color,attrs)+box(x,360,265,85,actions,'#f2f7fa','#bdced9',interactive?`class="cascade-node" role="button" tabindex="0" data-cascade-node="${b.id}" aria-label="${esc(b.action.join(' '))} erklären"`:'');
 }
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 720" width="1200" height="720" class="cascade-svg" role="${interactive?'group':'img'}" aria-labelledby="cascade-title cascade-desc"><title id="cascade-title">Eine Ursache, mehrere Folgen: Ende der Universitätsanbindung</title><desc id="cascade-desc">Ein mögliches Ende der institutionellen Anbindung kann Repo-Zugang, Werkzeugberechtigung, Beratung und Publikationsdienste betreffen. Jede Bedingung wird einzeln geprüft. Migration, Werkzeugzugang, Dokumentation und Prüfung des Publikationswegs helfen, die Weiterarbeit zu ermöglichen.</desc><defs><marker id="cascade-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M1 1L9 5L1 9" fill="none" stroke="#9baeb4" stroke-width="1.5"/></marker></defs><rect width="1200" height="720" fill="#fffefb"/><g font-family="Arial, sans-serif">${lines}${box(390,25,420,75,['Ende der','Universitätsanbindung'])}<rect x="480" y="125" width="240" height="34" rx="16" fill="#fffefb"/><text x="600" y="148" text-anchor="middle" font-size="16" fill="#52645b">kann mehrere Dienste betreffen</text>${nodes}${box(430,550,340,65,['Weiterarbeit ermöglichen'])}<text x="600" y="655" text-anchor="middle" font-size="16" fill="#173c39">Eine gemeinsame Ursache bedeutet nicht, dass alle Folgen eintreten.</text><text x="600" y="681" text-anchor="middle" font-size="14" fill="#52645b">Zugänge einzeln klären. Maßnahmen planen, prüfen und dokumentieren; ihre Wirkung ist noch nicht nachgewiesen.</text><text x="600" y="706" text-anchor="middle" font-size="12" fill="#52645b">Editionskompass · Anna · ${state?'aktueller Testfall':'neutrale Übersicht'} · 20. Oktober 2026</text></g></svg>`;
}
